<?php
declare(strict_types=1);
require_once __DIR__.'/app/bootstrap.php';
$code=trim((string)($_GET['code']??''));
if(!preg_match('/^BTA-\d{8}-[A-F0-9]{6}$/',$code)){http_response_code(404);exit('Booking not found.');}
$q=Database::connection()->prepare("SELECT b.booking_code,b.activity_date,b.activity_time,b.adults,b.children,b.participants,b.total_amount,b.currency,b.booking_status,b.payment_status,b.ticket_status,b.pickup_required,b.pickup_area_snapshot,b.pickup_address,b.pickup_fee_snapshot,b.reservation_expires_at,c.full_name,p.name package_name FROM bookings b JOIN customers c ON c.id=b.customer_id JOIN packages p ON p.id=b.package_id WHERE b.booking_code=:code LIMIT 1");
$q->execute(['code'=>$code]);$booking=$q->fetch();
if(!$booking){http_response_code(404);exit('Booking not found.');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Booking received | Bali Tarantula Adventure"><link rel="stylesheet" href="assets/css/style.css?v=20261029"><style>.success-wrap{max-width:780px;margin:0 auto;padding:55px 18px 85px}.success-card{background:#fff;color:#191919;border-top:4px solid #ff5a1f;padding:clamp(22px,5vw,42px);box-shadow:0 14px 40px #0001}.check{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:#e2f5e6;color:#16642a;font-size:27px;font-weight:900}.success-card h1{font-size:clamp(32px,7vw,54px);margin:18px 0 8px;line-height:1}.success-card>p{color:#5d5b56}.code{padding:14px;background:#f4f2ed;font-size:22px;font-weight:900;letter-spacing:1px;overflow-wrap:anywhere}.rows{margin:24px 0}.rows div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid #e7e3db}.rows span{color:#666}.rows strong{text-align:right;overflow-wrap:anywhere}.notice{background:#fff3e9;border-left:3px solid #ff5a1f;padding:15px;font-size:13px;line-height:1.7}.success-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:24px}@media(max-width:500px){.rows div{gap:10px}.rows strong{max-width:58%}}</style></head><body><?php require_once __DIR__.'/includes/header.php'; ?><main><section class="page-banner"><div class="wrap page-banner-content"><p class="eyebrow"><span class="eyebrow-line"></span> BOOKING REQUEST</p><h1>YOUR NEXT <span>ADVENTURE.</span></h1><p>Keep your booking code for any follow-up with our team.</p></div></section><section class="success-wrap"><article class="success-card"><div class="check">✓</div><h1>Booking received.</h1><p>Thanks, <?=e($booking['full_name'])?>. Your request has been recorded.</p><div class="code"><?=e($booking['booking_code'])?></div><div class="rows"><div><span>Package</span><strong><?=e($booking['package_name'])?></strong></div><div><span>Activity date</span><strong><?=e($booking['activity_date'])?> · <?=e(substr((string)$booking['activity_time'],0,5))?></strong></div><div><span>Participants</span><strong><?=(int)$booking['adults']?> adults, <?=(int)$booking['children']?> children</strong></div><div><span>Pickup</span><strong><?=$booking['pickup_required']?e(($booking['pickup_area_snapshot']??'Area pending').' — '.($booking['pickup_address']??'')):'Not requested'?></strong></div><div><span>Total</span><strong><?=e($booking['currency'])?> <?=number_format((float)$booking['total_amount'],2)?></strong></div><div><span>Booking status</span><strong><?=e($booking['booking_status'])?></strong></div><div><span>Payment status</span><strong><?=e($booking['payment_status'])?></strong></div><div><span>Ticket status</span><strong><?=e($booking['ticket_status'])?></strong></div></div><div class="notice">This booking is not yet paid or confirmed. The selected capacity is temporarily held until <?=e((string)$booking['reservation_expires_at'])?>. Please contact the team for official bank-transfer instructions. Do not consider this page a ticket; the ticket will be issued after payment is verified.</div><div class="success-actions"><a class="button button-orange" href="index.php">BACK TO HOME ↗</a><a class="button button-outline" href="packages.php">VIEW PACKAGES</a></div></article></section></main><?php require_once __DIR__.'/includes/footer.php'; ?></body></html>
